Definition ms_inb (i : Z) (iv : Z * Z) : bool := (fst iv <=? i) && (i <? fst iv + snd iv).
Definition ms_cov (L : list (Z * Z)) (i : Z) : bool := existsb (ms_inb i) L.

Lemma ms_inb_true : forall i o m, ms_inb i (o, m) = true <-> o <= i < o + m.
Proof.
  ltac2:(KReplay.run [|constr:(@Corelib.Numbers.BinNums.Z); constr:(@Corelib.Init.Logic.iff); constr:(@Corelib.Init.Logic.eq); constr:(@Corelib.Init.Datatypes.bool); constr:(@Corelib.Init.Datatypes.andb); constr:(@Stdlib.ZArith.BinInt.Z.leb); constr:(@Stdlib.ZArith.BinInt.Z.ltb); constr:(@Stdlib.ZArith.BinInt.Z.add); constr:(@Corelib.Init.Datatypes.true); constr:(@Corelib.Init.Logic.and); constr:(@Corelib.Classes.Morphisms.trans_co_eq_inv_impl_morphism); constr:(@Corelib.Classes.RelationClasses.iff_Transitive); constr:(@Stdlib.ZArith.BinInt.Z.le); constr:(@Stdlib.ZArith.BinInt.Z.lt); constr:(@Corelib.Classes.Morphisms.eq_proper_proxy); constr:(@Stdlib.Bool.Bool.andb_true_iff); constr:(@Corelib.Classes.Morphisms_Prop.and_iff_morphism); constr:(@Corelib.Classes.Morphisms.reflexive_proper_proxy); constr:(@Corelib.Classes.Morphisms.reflexive_reflexive_proxy); constr:(@Corelib.Classes.RelationClasses.iff_Reflexive); constr:(@Stdlib.ZArith.BinInt.Z.leb_le); constr:(@Corelib.Classes.Morphisms.Reflexive_partial_app_morphism); constr:(@Corelib.Classes.Morphisms.respectful); constr:(@Stdlib.ZArith.BinInt.Z.ltb_lt); constr:(@Corelib.Init.Logic.conj); constr:(@Corelib.Init.Logic.and_ind); constr:(@Corelib.Init.Datatypes.fst); constr:(@Corelib.Init.Datatypes.pair); constr:(@Corelib.Init.Datatypes.snd); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.As.MemsetLib.ms_inb)|] [|@lemma; @B; @H1; @H0; @H; @m; @o; @i|] "##n#)#H#%#)#-#,#/#4#$###&#7#'#=#<#5#(#D#:#;#>#?#@#B#A#C#E#G#F#H#I#.#3#9#1#2#0#8#6-#@&#A%#0%#%%#B%#C%#D%#E%#F%#G,(IC$IJ)C#*%##G#H#G'H#G&H%$#&&#(CK$CI)K#*%##G#H#G'H#G&H%$#+CK'K*%$#VS#D#,DEL*'J$$#j#$0#VS$97+IC&6#%+-WS%DES&XNDE#/ZO1.J00#,DEL0&#--,j#$(#VS'IC'CB&>#k#%DDXS(DDEEXNDE,6_S)D%E$PO7#96J,DEL/6#665j#$(#VS*Cs#*%4+k###:$KC'M#+MQ$MK'Q#XR%#IJj#&'#j#'s#$#YS+s#%s#$s###Jj#(-#XR--##V10#V;:#Vs#%s#$#XS,FFIJWS-FF#(#CWS.FF%$%#)C#*&##G#H&#:m#,#VS/C,#G#H&#>m#&#j#)F#j#*F#j#+F##"). Qed.

Lemma ms_cov_cons : forall iv L i, ms_cov (iv :: L) i = ms_inb i iv || ms_cov L i.
Proof. reflexivity. Qed.

Lemma ms_cov_app : forall L1 L2 i, ms_cov (L1 ++ L2) i = ms_cov L1 i || ms_cov L2 i.
Proof. intros. unfold ms_cov. apply existsb_app. Qed.

Lemma ms_cov_In : forall L i o m, In (o, m) L -> o <= i < o + m -> ms_cov L i = true.
Proof.
  intros L i o m Hin Hi. unfold ms_cov. apply existsb_exists. exists (o, m). split; [exact Hin|].
  apply ms_inb_true. exact Hi.
Qed.

(* [comment removed for export] *)
Fixpoint ms_chain (from to : Z) (L : list (Z * Z)) : Prop :=
  match L with
  | [] => to <= from
  | (o, m) :: L' => o <= from /\ ms_chain (o + m) to L'
  end.

Lemma ms_chain_cov : forall L from to i,
  ms_chain from to L -> from <= i < to -> exists o m, In (o, m) L /\ o <= i < o + m.
Proof.
  induction L as [|[o m] L IH]; intros from to i Hc Hi; cbn [ms_chain] in Hc.
  - lia.
  - destruct Hc as [Ho Hc].
    destruct (Z.lt_ge_cases i (o + m)) as [Hlt|Hge].
    + exists o, m. split; [left; reflexivity | lia].
    + destruct (IH (o + m) to i Hc ltac:(lia)) as (o' & m' & Hin & Hi').
      exists o', m'. split; [right; exact Hin | exact Hi'].
Qed.

(* [comment removed for export] *)
Lemma ms_cov_by_chain : forall (L L' : list (Z * Z)) n,
  incl L' L -> ms_chain 0 n L' -> forall i, 0 <= i < n -> ms_cov L i = true.
Proof.
  intros L L' n Hincl Hc i Hi.
  destruct (ms_chain_cov L' 0 n i Hc Hi) as (o & m & Hin & Hom).
  apply (ms_cov_In L i o m); [apply Hincl, Hin | exact Hom].
Qed.

